<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {createConversation,listBases,listConversations,listMessages,sendMessage,getModelSettings,previewDocument,type Citation} from '../api/client'
const bases=ref<any[]>([]),selectedKb=ref(''),conversations=ref<any[]>([]),conversationId=ref(''),messages=ref<any[]>([]),question=ref(''),mode=ref<'STRICT'|'SUPPLEMENT'>('STRICT'),busy=ref(false),error=ref(''),preview=ref(''),previewTitle=ref(''),generationProvider=ref('OLLAMA'),embeddingProvider=ref('OLLAMA'),embeddingExplicitlyConfigured=ref(false)
let controller:AbortController|undefined
const chosenBase=computed(()=>bases.value.find(b=>(b.ID||b.id)===selectedKb.value))
const val=(x:any,k:string)=>x[k.toUpperCase()]??x[k]
async function loadBases(){const r=await listBases();bases.value=r.items||[];if(!selectedKb.value&&bases.value.length)await chooseKb(bases.value[0])}
async function chooseKb(base:any){selectedKb.value=base.ID||base.id;conversationId.value='';messages.value=[];await loadConversations()}
async function loadConversations(){if(!selectedKb.value)return;try{const r=await listConversations(selectedKb.value);conversations.value=r.items||[]}catch(e:any){error.value=e.message}}
async function newConversation(){try{const c=await createConversation(selectedKb.value);conversationId.value=c.id;messages.value=[];await loadConversations()}catch(e:any){error.value=e.message}}
async function selectConversation(id:string){conversationId.value=id;try{const r=await listMessages(id);messages.value=(r||[]).map((m:any)=>({id:m.ID||m.id,role:m.ROLE||m.role,content:m.CONTENT||m.content,mode:m.MODE||m.mode,status:m.STATUS||m.status,citations:m.citations||[]}))}catch(e:any){error.value=e.message}}
async function submit(){const text=question.value.trim();if(!text||busy.value||!selectedKb.value)return;error.value='';const disclosures:string[]=[];if(embeddingProvider.value==='OPENAI_COMPATIBLE'&&!embeddingExplicitlyConfigured.value)disclosures.push('当前公共嵌入配置尚未明确保存，继续会将本次问题文本发送给兼容公共 API 以生成查询向量');else if(embeddingProvider.value==='OPENAI_COMPATIBLE')disclosures.push('本次问题文本会发送给兼容公共 API 嵌入服务以生成查询向量');if(generationProvider.value==='OPENAI_COMPATIBLE')disclosures.push('本次问题及检索到的资料片段会发送给兼容公共 API 生成服务');if(disclosures.length&&!window.confirm(disclosures.join('；')+'。继续吗？'))return;if(!conversationId.value)await newConversation();if(!conversationId.value)return
 const user={id:crypto.randomUUID(),role:'user',content:text,status:'COMPLETED'},assistant={id:crypto.randomUUID(),role:'assistant',content:'',citations:[],status:'STREAMING'};messages.value.push(user,assistant);question.value='';busy.value=true;controller=new AbortController()
 try{await sendMessage(conversationId.value,{content:text,mode:mode.value,topK:5},{token:t=>assistant.content+=t,citation:c=>assistant.citations.push(c),completed:id=>{assistant.id=id;assistant.status='COMPLETED'},failed:e=>{assistant.status='FAILED';assistant.content=e.message;assistant.errorCode=e.code}},controller.signal)}catch(e:any){if(e.name!=='AbortError'){assistant.status='FAILED';assistant.content=e.message}}finally{busy.value=false;controller=undefined;loadConversations()}}
 async function openCitation(c:Citation){try{const r=await previewDocument(c.documentId);previewTitle.value=`${c.name} · ${c.location}`;preview.value=r.text||c.snippet}catch(e:any){error.value=e.message}}
async function load(){try{const cfg=await getModelSettings();generationProvider.value=cfg.generation.provider;embeddingProvider.value=cfg.embedding.provider;embeddingExplicitlyConfigured.value=Boolean(cfg.embedding.explicitlyConfigured);await loadBases()}catch(e:any){error.value=e.message}}
 onMounted(load);onUnmounted(()=>controller?.abort())
</script>
<template><section class="chat-layout"><aside class="card chat-sidebar"><h2>知识库问答</h2><label>知识库<select v-model="selectedKb" @change="chosenBase&&chooseKb(chosenBase)"><option v-for="b in bases" :key="val(b,'id')" :value="val(b,'id')">{{val(b,'name')}}</option></select></label><button :disabled="!selectedKb" @click="newConversation">新建会话</button><div class="conversation-list"><button v-for="c in conversations" :key="val(c,'id')" class="conversation-item" :class="{chosen:conversationId===val(c,'id')}" @click="selectConversation(val(c,'id'))">{{val(c,'title')}}</button></div><p v-if="generationProvider==='OPENAI_COMPATIBLE'||embeddingProvider==='OPENAI_COMPATIBLE'" class="privacy-note">公共 API 模式会发送问题文本；若生成服务也使用公共 API，还会发送相关资料片段。发送前会再次确认。</p></aside><main class="card chat-main"><p v-if="error" class="error">{{error}}</p><div v-if="!selectedKb" class="empty-state">先在知识库页面创建知识库并导入资料。</div><div v-else-if="!conversationId" class="empty-state">选择或新建会话，开始基于当前知识库提问。</div><div v-else class="messages" aria-live="polite"><article v-for="m in messages" :key="m.id" class="message" :class="m.role"><strong>{{m.role==='user'?'你':'知识库助手'}}</strong><p>{{m.content|| (m.status==='STREAMING'?'正在生成…':'')}}</p><div v-if="m.citations?.length" class="citations"><span>资料来源</span><button v-for="c in m.citations" :key="c.chunkId" class="citation" @click="openCitation(c)">{{c.name}} · {{c.location}} <small>{{Math.round(c.score*100)}}%</small></button></div></article></div><div class="composer"><select v-model="mode" aria-label="回答模式"><option value="STRICT">严格依据资料</option><option value="SUPPLEMENT">资料加通用补充</option></select><textarea v-model="question" rows="3" placeholder="在当前知识库中提问…" @keydown.ctrl.enter="submit"></textarea><button :disabled="busy||!question.trim()" @click="submit">{{busy?'生成中…':'发送'}}</button><button v-if="busy" class="secondary" @click="controller?.abort()">停止</button></div></main><div v-if="preview" class="preview-panel"><button class="close" @click="preview='';previewTitle=''">关闭</button><h3>{{previewTitle}}</h3><pre>{{preview}}</pre></div></section></template>
